import java.math.BigInteger;

class Solution {
    public String abbreviateProduct(int left, int right) {
        BigInteger product = BigInteger.ONE;
        int twos = 0;
        int fives = 0;

        for (int i = left; i <= right; i++) {
            int value = i;

            while (value % 2 == 0) {
                twos++;
                value /= 2;
            }

            while (value % 5 == 0) {
                fives++;
                value /= 5;
            }

            product = product.multiply(BigInteger.valueOf(value));
        }

        int zeros = Math.min(twos, fives);
        twos -= zeros;
        fives -= zeros;

        if (twos > 0) {
            product = product.shiftLeft(twos);
        }
        if (fives > 0) {
            product = product.multiply(BigInteger.valueOf(5).pow(fives));
        }

        String value = product.toString();

        if (value.length() <= 10) {
            return value + "e" + zeros;
        }

        return value.substring(0, 5)
                + "..."
                + value.substring(value.length() - 5)
                + "e"
                + zeros;
    }
}
