class Solution {
    public int countTriples(int n) {
        boolean[] squares = new boolean[n * n + 1];

        for (int c = 1; c <= n; c++) {
            squares[c * c] = true;
        }

        int count = 0;
        for (int a = 1; a <= n; a++) {
            for (int b = 1; b <= n; b++) {
                if (squares[a * a + b * b]) {
                    count++;
                }
            }
        }

        return count;
    }
}
