class Solution {
    public int[] hitBricks(int[][] grid, int[][] hits) {
        int m = grid.length;
        int n = grid[0].length;
        int roof = m * n;
        int[] result = new int[hits.length];
        boolean[] removed = new boolean[hits.length];

        for (int i = 0; i < hits.length; i++) {
            int row = hits[i][0];
            int col = hits[i][1];

            if (grid[row][col] == 1) {
                removed[i] = true;
                grid[row][col] = 0;
            }
        }

        UnionFind uf = new UnionFind(m * n + 1);
        int[][] directions = {{1, 0}, {0, 1}};

        for (int row = 0; row < m; row++) {
            for (int col = 0; col < n; col++) {
                if (grid[row][col] == 0) {
                    continue;
                }

                int index = row * n + col;
                if (row == 0) {
                    uf.union(index, roof);
                }

                for (int[] direction : directions) {
                    int nextRow = row + direction[0];
                    int nextCol = col + direction[1];

                    if (nextRow < m && nextCol < n
                            && grid[nextRow][nextCol] == 1) {
                        uf.union(index, nextRow * n + nextCol);
                    }
                }
            }
        }

        int[][] neighbors = {
            {-1, 0}, {1, 0}, {0, -1}, {0, 1}
        };

        for (int i = hits.length - 1; i >= 0; i--) {
            if (!removed[i]) {
                continue;
            }

            int row = hits[i][0];
            int col = hits[i][1];
            int before = uf.componentSize(roof);

            grid[row][col] = 1;
            int index = row * n + col;

            if (row == 0) {
                uf.union(index, roof);
            }

            for (int[] neighbor : neighbors) {
                int nextRow = row + neighbor[0];
                int nextCol = col + neighbor[1];

                if (nextRow >= 0 && nextRow < m
                        && nextCol >= 0 && nextCol < n
                        && grid[nextRow][nextCol] == 1) {
                    uf.union(index, nextRow * n + nextCol);
                }
            }

            int after = uf.componentSize(roof);
            result[i] = Math.max(0, after - before - 1);
        }

        return result;
    }

    private static class UnionFind {
        private final int[] parent;
        private final int[] size;

        UnionFind(int n) {
            parent = new int[n];
            size = new int[n];

            for (int i = 0; i < n; i++) {
                parent[i] = i;
                size[i] = 1;
            }
        }

        int find(int node) {
            if (parent[node] != node) {
                parent[node] = find(parent[node]);
            }
            return parent[node];
        }

        void union(int first, int second) {
            int rootFirst = find(first);
            int rootSecond = find(second);

            if (rootFirst == rootSecond) {
                return;
            }

            if (size[rootFirst] < size[rootSecond]) {
                int temp = rootFirst;
                rootFirst = rootSecond;
                rootSecond = temp;
            }

            parent[rootSecond] = rootFirst;
            size[rootFirst] += size[rootSecond];
        }

        int componentSize(int node) {
            return size[find(node)];
        }
    }
}
