class Solution {
    public int clumsy(int n) {
        java.util.Deque<Integer> stack = new java.util.ArrayDeque<>();
        stack.push(n--);

        int operation = 0;

        while (n > 0) {
            if (operation == 0) {
                stack.push(stack.pop() * n);
            } else if (operation == 1) {
                stack.push(stack.pop() / n);
            } else if (operation == 2) {
                stack.push(n);
            } else {
                stack.push(-n);
            }

            operation = (operation + 1) % 4;
            n--;
        }

        int result = 0;
        while (!stack.isEmpty()) {
            result += stack.pop();
        }
        return result;
    }
}
