    public int[] numSmallerByFrequency(String[] queries, String[] words) {
        int[] frequencyCounts = new int[11];

        for (String word : words) {
            frequencyCounts[smallestCharFrequency(word)]++;
        }

        for (int i = 9; i >= 0; i--) {
            frequencyCounts[i] += frequencyCounts[i + 1];
        }

        int[] answer = new int[queries.length];
        for (int i = 0; i < queries.length; i++) {
            int queryFrequency = smallestCharFrequency(queries[i]);
            answer[i] = queryFrequency < 10 ? frequencyCounts[queryFrequency + 1] : 0;
        }

        return answer;
    }

    private int smallestCharFrequency(String s) {
        char smallest = Character.MAX_VALUE;
        int frequency = 0;

        for (int i = 0; i < s.length(); i++) {
            char current = s.charAt(i);

            if (current < smallest) {
                smallest = current;
                frequency = 1;
            } else if (current == smallest) {
                frequency++;
            }
        }

        return frequency;
