class Solution {
    public int countMaxOrSubsets(int[] nums) {
        int maxOr = 0;
        for (int num : nums) {
            maxOr |= num;
        }

        int count = 0;
        int totalMasks = 1 << nums.length;

        for (int mask = 1; mask < totalMasks; mask++) {
            int currentOr = 0;

            for (int i = 0; i < nums.length; i++) {
                if ((mask & (1 << i)) != 0) {
                    currentOr |= nums[i];
                }
            }

            if (currentOr == maxOr) {
                count++;
            }
        }

        return count;
    }
}
