class Solution {
    public int countVowelSubstrings(String word) {
        int[] lastSeen = {-1, -1, -1, -1, -1};
        int lastConsonant = -1;
        int count = 0;

        for (int i = 0; i < word.length(); i++) {
            int vowelIndex;

            switch (word.charAt(i)) {
                case 'a':
                    vowelIndex = 0;
                    break;
                case 'e':
                    vowelIndex = 1;
                    break;
                case 'i':
                    vowelIndex = 2;
                    break;
                case 'o':
                    vowelIndex = 3;
                    break;
                case 'u':
                    vowelIndex = 4;
                    break;
                default:
                    vowelIndex = -1;
            }

            if (vowelIndex == -1) {
                lastConsonant = i;
            } else {
                lastSeen[vowelIndex] = i;

                int earliestVowel = lastSeen[0];
                for (int position : lastSeen) {
                    earliestVowel = Math.min(earliestVowel, position);
                }

                if (earliestVowel > lastConsonant) {
                    count += earliestVowel - lastConsonant;
                }
            }
        }

        return count;
    }
}
