/**
 * Definition for a binary tree node.
 * public class TreeNode {
 *     int val;
 *     TreeNode left;
 *     TreeNode right;
 *     TreeNode() {}
 *     TreeNode(int val) { this.val = val; }
 *     TreeNode(int val, TreeNode left, TreeNode right) {
 *         this.val = val;
 *         this.left = left;
 *         this.right = right;
 *     }
 * }
 */
class Solution {
    public boolean isCousins(TreeNode root, int x, int y) {
        java.util.Queue<TreeNode> queue = new java.util.ArrayDeque<>();
        queue.offer(root);

        while (!queue.isEmpty()) {
            int size = queue.size();
            boolean foundX = false;
            boolean foundY = false;

            for (int i = 0; i < size; i++) {
                TreeNode node = queue.poll();

                boolean leftIsX = node.left != null && node.left.val == x;
                boolean rightIsX = node.right != null && node.right.val == x;
                boolean leftIsY = node.left != null && node.left.val == y;
                boolean rightIsY = node.right != null && node.right.val == y;

                if ((leftIsX && rightIsY) || (leftIsY && rightIsX)) {
                    return false;
                }

                if (node.left != null) {
