class Solution {
    public boolean canCross(int[] stones) {
        int n = stones.length;
        if (stones[1] != 1) {
            return false;
        }

        java.util.Map<Integer, Integer> positionToIndex = new java.util.HashMap<>();
        for (int i = 0; i < n; i++) {
            positionToIndex.put(stones[i], i);
        }

        boolean[][] reachable = new boolean[n][n + 1];
        reachable[0][0] = true;

        for (int i = 0; i < n; i++) {
            for (int jump = 0; jump <= n; jump++) {
                if (!reachable[i][jump]) {
                    continue;
                }

                for (int nextJump = jump - 1; nextJump <= jump + 1; nextJump++) {
                    if (nextJump <= 0 || nextJump > n) {
                        continue;
                    }

                    long nextPosition = (long) stones[i] + nextJump;
                    if (nextPosition > Integer.MAX_VALUE) {
                        continue;
                    }

                    Integer nextIndex = positionToIndex.get((int) nextPosition);
                    if (nextIndex == null) {
                        continue;
                    }
                    if (nextIndex == n - 1) {
                        return true;
                    }

                    reachable[nextIndex][nextJump] = true;
                }
            }
        }

        return false;
    }
}
