class Solution {
    public int maxScore(int[] nums) {
        int length = nums.length;
        int[][] gcd = new int[length][length];

        for (int i = 0; i < length; i++) {
            for (int j = i + 1; j < length; j++) {
                gcd[i][j] = gcd(nums[i], nums[j]);
            }
        }

        int fullMask = (1 << length) - 1;
        int[] dp = new int[1 << length];

        for (int mask = 0; mask < fullMask; mask++) {
            int used = Integer.bitCount(mask);
            if ((used & 1) != 0 || (mask != 0 && dp[mask] == 0)) {
                continue;
            }

            int operation = used / 2 + 1;

            for (int i = 0; i < length; i++) {
                if ((mask & (1 << i)) != 0) {
                    continue;
                }

                for (int j = i + 1; j < length; j++) {
                    if ((mask & (1 << j)) != 0) {
                        continue;
                    }

                    int nextMask = mask | (1 << i) | (1 << j);
                    dp[nextMask] = Math.max(
                        dp[nextMask],
                        dp[mask] + operation * gcd[i][j]
                    );
                }
            }
        }

        return dp[fullMask];
    }

    private int gcd(int a, int b) {
        while (b != 0) {
            int remainder = a % b;
            a = b;
            b = remainder;
        }
        return a;
    }
}
