class Solution {
    public int maximumANDSum(int[] nums, int numSlots) {
        int[] powerOfThree = new int[numSlots + 1];
        powerOfThree[0] = 1;
        for (int i = 1; i <= numSlots; i++) {
            powerOfThree[i] = powerOfThree[i - 1] * 3;
        }

        int states = powerOfThree[numSlots];
        int[] dp = new int[states];
        int[] used = new int[states];
        java.util.Arrays.fill(dp, -1);
        dp[0] = 0;

        for (int mask = 1; mask < states; mask++) {
            used[mask] = used[mask / 3] + mask % 3;
        }

        int answer = 0;

        for (int mask = 0; mask < states; mask++) {
            if (dp[mask] < 0) {
                continue;
            }

            int index = used[mask];
            if (index == nums.length) {
                answer = Math.max(answer, dp[mask]);
                continue;
            }

            for (int slot = 0; slot < numSlots; slot++) {
                int occupancy = (mask / powerOfThree[slot]) % 3;
                if (occupancy < 2) {
                    int nextMask = mask + powerOfThree[slot];
                    int score = dp[mask] + (nums[index] & (slot + 1));
                    dp[nextMask] = Math.max(dp[nextMask], score);
                }
            }
        }

        return answer;
    }
}
