class Solution {
    public String maximumBinaryString(String binary) {
        int firstZero = binary.indexOf('0');
        if (firstZero == -1) {
            return binary;
        }

        int zeroCount = 0;
        for (int i = firstZero; i < binary.length(); i++) {
            if (binary.charAt(i) == '0') {
                zeroCount++;
            }
        }

        char[] result = new char[binary.length()];
        for (int i = 0; i < result.length; i++) {
