class Solution {
    public int maxTotalFruits(int[][] fruits, int startPos, int k) {
        int left = 0;
        int total = 0;
        int answer = 0;

        for (int right = 0; right < fruits.length; right++) {
            total += fruits[right][1];

            while (left <= right &&
                   stepsNeeded(fruits[left][0], fruits[right][0], startPos) > k) {
                total -= fruits[left][1];
                left++;
            }

            answer = Math.max(answer, total);
        }

        return answer;
    }

    private int stepsNeeded(int left, int right, int startPos) {
        if (right <= startPos) {
            return startPos - left;
        }
        if (left >= startPos) {
            return right - startPos;
        }

        int leftDistance = startPos - left;
        int rightDistance = right - startPos;

        return Math.min(
            2 * leftDistance + rightDistance,
            leftDistance + 2 * rightDistance
        );
    }
}
