class Solution {
    public int maxStudents(char[][] seats) {
        int rows = seats.length;
        int cols = seats[0].length;
        int limit = 1 << cols;

        int[] available = new int[rows];
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (seats[r][c] == '.') {
                    available[r] |= 1 << c;
                }
            }
        }

        int[] previous = new int[limit];
        java.util.Arrays.fill(previous, -1);
        previous[0] = 0;

        for (int r = 0; r < rows; r++) {
            int[] current = new int[limit];
            java.util.Arrays.fill(current, -1);

            for (int mask = 0; mask < limit; mask++) {
                if ((mask & ~available[r]) != 0 || (mask & (mask << 1)) != 0) {
                    continue;
                }

                int students = Integer.bitCount(mask);

                for (int prevMask = 0; prevMask < limit; prevMask++) {
                    if (previous[prevMask] < 0) {
                        continue;
                    }
                    if ((mask & (prevMask << 1)) != 0
                            || (mask & (prevMask >> 1)) != 0) {
                        continue;
                    }

                    current[mask] = Math.max(
                            current[mask],
                            previous[prevMask] + students
                    );
                }
            }

            previous = current;
        }

        int answer = 0;
        for (int value : previous) {
            answer = Math.max(answer, value);
        }
        return answer;
    }
}
