class Solution {
    public int maxSumTwoNoOverlap(int[] nums, int firstLen, int secondLen) {
        int n = nums.length;
        int[] prefix = new int[n + 1];

        for (int i = 0; i < n; i++) {
            prefix[i + 1] = prefix[i] + nums[i];
        }

        int maxFirst = 0;
        int maxSecond = 0;
        int answer = 0;

        for (int end = firstLen + secondLen; end <= n; end++) {
            maxFirst = Math.max(
                maxFirst,
                prefix[end - secondLen] - prefix[end - secondLen - firstLen]
            );

            maxSecond = Math.max(
                maxSecond,
                prefix[end - firstLen] - prefix[end - firstLen - secondLen]
            );

            int secondAtEnd = prefix[end] - prefix[end - secondLen];
            int firstAtEnd = prefix[end] - prefix[end - firstLen];

            answer = Math.max(answer, maxFirst + secondAtEnd);
            answer = Math.max(answer, maxSecond + firstAtEnd);
        }

        return answer;
    }
