            long beauty = (long) complete * full;

            if (remaining > 0) {
                long budget = newFlowers - completionCost;
                int minimum = maximumMinimum(flowers, prefix, remaining, budget, target);
                beauty += (long) minimum * partial;
            }

            answer = Math.max(answer, beauty);

            if (remaining > 0) {
                completionCost += (long) target - flowers[remaining - 1];
            }
        }

        return answer;
    }

    private int maximumMinimum(int[] flowers, long[] prefix, int size,
                               long budget, int target) {
        int low = 0;
        int high = target - 1;

        while (low <= high) {
            int mid = low + (high - low) / 2;
            int count = lowerBound(flowers, size, mid);
            long cost = (long) mid * count - prefix[count];

            if (cost <= budget) {
                low = mid + 1;
            } else {
                high = mid - 1;
            }
        }

        return high;
    }

    private int lowerBound(int[] values, int size, int target) {
        int low = 0;
        int high = size;

        while (low < high) {
            int mid = low + (high - low) / 2;
            if (values[mid] < target) {
                low = mid + 1;
            } else {
                high = mid;
            }
        }

        return low;
    }
