    public int minSessions(int[] tasks, int sessionTime) {
        int n = tasks.length;
        int totalMasks = 1 << n;
        int[] sessions = new int[totalMasks];
        int[] usedTime = new int[totalMasks];

        java.util.Arrays.fill(sessions, n + 1);
        java.util.Arrays.fill(usedTime, sessionTime + 1);

        sessions[0] = 1;
        usedTime[0] = 0;

        for (int mask = 0; mask < totalMasks; mask++) {
            for (int i = 0; i < n; i++) {
                if ((mask & (1 << i)) != 0) {
                    continue;
                }

                int nextMask = mask | (1 << i);
                int nextSessions = sessions[mask];
