class Solution {
    public int[] nextGreaterElements(int[] nums) {
        int n = nums.length;
        int[] result = new int[n];
        int[] stack = new int[n];
        int top = -1;

        for (int i = 0; i < n; i++) {
            result[i] = -1;
        }

        for (int i = 0; i < 2 * n; i++) {
            int index = i % n;

            while (top >= 0 && nums[stack[top]] < nums[index]) {
                result[stack[top--]] = nums[index];
            }

            if (i < n) {
                stack[++top] = index;
            }
        }

        return result;
    }
}
