class Solution {
    private static final int MOD = 1_000_000_007;

    public int numOfWays(int[] nums) {
        int n = nums.length;
        int[][] combinations = new int[n + 1][n + 1];

        for (int i = 0; i <= n; i++) {
            combinations[i][0] = combinations[i][i] = 1;
            for (int j = 1; j < i; j++) {
                combinations[i][j] = (int) (
                    ((long) combinations[i - 1][j - 1] + combinations[i - 1][j]) % MOD
                );
            }
        }

        int[] left = new int[n + 1];
        int[] right = new int[n + 1];
        int root = nums[0];

        for (int i = 1; i < n; i++) {
            int value = nums[i];
            int current = root;

            while (true) {
                if (value < current) {
                    if (left[current] == 0) {
                        left[current] = value;
                        break;
                    }
                    current = left[current];
                } else {
                    if (right[current] == 0) {
                        right[current] = value;
                        break;
                    }
                    current = right[current];
                }
            }
        }

        int[] subtreeSize = new int[n + 1];
        long[] ways = new long[n + 1];
        countWays(root, left, right, subtreeSize, ways, combinations);

        return (int) ((ways[root] - 1 + MOD) % MOD);
    }

    private void countWays(
        int node,
        int[] left,
        int[] right,
        int[] subtreeSize,
        long[] ways,
        int[][] combinations
    ) {
        if (node == 0) {
            return;
        }

        countWays(left[node], left, right, subtreeSize, ways, combinations);
        countWays(right[node], left, right, subtreeSize, ways, combinations);

        int leftSize = left[node] == 0 ? 0 : subtreeSize[left[node]];
        int rightSize = right[node] == 0 ? 0 : subtreeSize[right[node]];

        long leftWays = left[node] == 0 ? 1 : ways[left[node]];
        long rightWays = right[node] == 0 ? 1 : ways[right[node]];

        ways[node] = combinations[leftSize + rightSize][leftSize];
        ways[node] = ways[node] * leftWays % MOD;
        ways[node] = ways[node] * rightWays % MOD;

        subtreeSize[node] = leftSize + rightSize + 1;
    }
}
