    private long countTriplets(int[] squaredNumbers, int[] factors) {
        java.util.Map<Long, Integer> squareFrequency = new java.util.HashMap<>();

        for (int number : squaredNumbers) {
            long square = (long) number * number;
            squareFrequency.merge(square, 1, Integer::sum);
        }

        long count = 0;

        for (int j = 0; j < factors.length; j++) {
            for (int k = j + 1; k < factors.length; k++) {
                long product = (long) factors[j] * factors[k];
                count += squareFrequency.getOrDefault(product, 0);
            }
        }

        return count;
    }
