class Solution {
    public boolean canPartitionKSubsets(int[] nums, int k) {
        int total = 0;
        for (int num : nums) {
            total += num;
        }

        if (total % k != 0) {
            return false;
        }

        int target = total / k;
        for (int num : nums) {
            if (num > target) {
                return false;
            }
        }

        int size = 1 << nums.length;
        int[] dp = new int[size];
        java.util.Arrays.fill(dp, -1);
        dp[0] = 0;

        for (int mask = 0; mask < size; mask++) {
            if (dp[mask] == -1) {
                continue;
            }

            for (int i = 0; i < nums.length; i++) {
                int bit = 1 << i;
                if ((mask & bit) == 0 && dp[mask] + nums[i] <= target) {
                    dp[mask | bit] = (dp[mask] + nums[i]) % target;
                }
            }
        }

        return dp[size - 1] == 0;
    }
}
