class Solution {
    public int maxSizeSlices(int[] slices) {
        int picks = slices.length / 3;
        return Math.max(
            maxLinear(slices, 0, slices.length - 2, picks),
            maxLinear(slices, 1, slices.length - 1, picks)
        );
    }

    private int maxLinear(int[] slices, int start, int end, int picks) {
        int length = end - start + 1;
        int[][] dp = new int[length + 1][picks + 1];
        int impossible = Integer.MIN_VALUE / 2;

        for (int i = 0; i <= length; i++) {
            for (int j = 1; j <= picks; j++) {
                dp[i][j] = impossible;
            }
        }

        for (int i = 1; i <= length; i++) {
            for (int j = 1; j <= picks; j++) {
                dp[i][j] = dp[i - 1][j];

                int previous = i >= 2 ? dp[i - 2][j - 1] : dp[0][j - 1];
                if (previous != impossible) {
                    dp[i][j] = Math.max(
                        dp[i][j],
                        previous + slices[start + i - 1]
                    );
                }
            }
        }

        return dp[length][picks];
    }
}
