    private int[] size;

    public boolean[] friendRequests(int n, int[][] restrictions, int[][] requests) {
        parent = new int[n];
        size = new int[n];

        for (int i = 0; i < n; i++) {
            parent[i] = i;
            size[i] = 1;
        }

        boolean[] result = new boolean[requests.length];

        for (int i = 0; i < requests.length; i++) {
            int rootU = find(requests[i][0]);
            int rootV = find(requests[i][1]);

            if (rootU == rootV) {
                result[i] = true;
                continue;
            }

            boolean allowed = true;

            for (int[] restriction : restrictions) {
                int rootX = find(restriction[0]);
                int rootY = find(restriction[1]);

                if ((rootX == rootU && rootY == rootV)
                        || (rootX == rootV && rootY == rootU)) {
                    allowed = false;
                    break;
                }
            }

            if (allowed) {
                union(rootU, rootV);
                result[i] = true;
            }
        }

        return result;
    }

    private int find(int node) {
        if (parent[node] != node) {
            parent[node] = find(parent[node]);
        }
        return parent[node];
    }

    private void union(int rootA, int rootB) {
        rootA = find(rootA);
        rootB = find(rootB);

        if (rootA == rootB) {
            return;
        }

        if (size[rootA] < size[rootB]) {
            int temp = rootA;
            rootA = rootB;
            rootB = temp;
        }

        parent[rootB] = rootA;
        size[rootA] += size[rootB];
    }
}
