class Solution {
    public int splitArray(int[] nums, int k) {
        long left = 0;
        long right = 0;

        for (int num : nums) {
            left = Math.max(left, num);
            right += num;
        }

        while (left < right) {
            long mid = left + (right - left) / 2;
            int subarrays = 1;
            long currentSum = 0;

            for (int num : nums) {
                if (currentSum + num > mid) {
                    subarrays++;
                    currentSum = num;
                } else {
                    currentSum += num;
                }
            }

            if (subarrays <= k) {
                right = mid;
            } else {
                left = mid + 1;
            }
        }

        return (int) left;
    }
}
