import java.util.Arrays;

class Solution {
    public int[] getCoprimes(int[] nums, int[][] edges) {
        int n = nums.length;
        int[] degree = new int[n];

        for (int[] edge : edges) {
            degree[edge[0]]++;
            degree[edge[1]]++;
        }

        int[][] graph = new int[n][];
        for (int i = 0; i < n; i++) {
            graph[i] = new int[degree[i]];
        }

        int[] index = new int[n];
        for (int[] edge : edges) {
            int u = edge[0];
            int v = edge[1];
            graph[u][index[u]++] = v;
            graph[v][index[v]++] = u;
        }

        boolean[][] coprime = new boolean[51][51];
        for (int i = 1; i <= 50; i++) {
            for (int j = 1; j <= 50; j++) {
                coprime[i][j] = gcd(i, j) == 1;
            }
        }

        int[] answer = new int[n];
        Arrays.fill(answer, -1);

        int[] parent = new int[n];
        Arrays.fill(parent, -1);

        int[] depth = new int[n];
        int[] topNode = new int[51];
        Arrays.fill(topNode, -1);

        int[] previousTop = new int[n];
        int[] stack = new int[2 * n + 5];
        int size = 0;
        stack[size++] = 0;

        while (size > 0) {
            int event = stack[--size];

            if (event >= 0) {
                int node = event;
                int value = nums[node];
                int closest = -1;
                int closestDepth = -1;

                for (int candidateValue = 1; candidateValue <= 50; candidateValue++) {
                    int candidateNode = topNode[candidateValue];
                    if (candidateNode != -1
                            && coprime[value][candidateValue]
                            && depth[candidateNode] > closestDepth) {
                        closestDepth = depth[candidateNode];
                        closest = candidateNode;
                    }
                }

                answer[node] = closest;
                previousTop[node] = topNode[value];
                topNode[value] = node;

                stack[size++] = ~node;

                for (int neighbor : graph[node]) {
                    if (neighbor == parent[node]) {
                        continue;
                    }
                    parent[neighbor] = node;
                    depth[neighbor] = depth[node] + 1;
                    stack[size++] = neighbor;
                }
            } else {
                int node = ~event;
                topNode[nums[node]] = previousTop[node];
            }
        }

        return answer;
    }

    private int gcd(int a, int b) {
        while (b != 0) {
            int remainder = a % b;
            a = b;
            b = remainder;
        }
        return a;
    }
}
