import java.util.*;

class Solution {
    public int ladderLength(String beginWord, String endWord, List<String> wordList) {
        Set<String> dictionary = new HashSet<>(wordList);
        if (!dictionary.contains(endWord)) {
            return 0;
        }

        Set<String> beginFrontier = new HashSet<>();
        Set<String> endFrontier = new HashSet<>();
        beginFrontier.add(beginWord);
        endFrontier.add(endWord);

        dictionary.remove(beginWord);
        dictionary.remove(endWord);

        int length = 1;

        while (!beginFrontier.isEmpty() && !endFrontier.isEmpty()) {
            if (beginFrontier.size() > endFrontier.size()) {
                Set<String> temp = beginFrontier;
                beginFrontier = endFrontier;
                endFrontier = temp;
            }

            Set<String> nextFrontier = new HashSet<>();

            for (String word : beginFrontier) {
                char[] letters = word.toCharArray();

                for (int i = 0; i < letters.length; i++) {
                    char original = letters[i];

                    for (char c = 'a'; c <= 'z'; c++) {
                        if (c == original) {
                            continue;
                        }

                        letters[i] = c;
                        String nextWord = new String(letters);

                        if (endFrontier.contains(nextWord)) {
                            return length + 1;
                        }

                        if (dictionary.remove(nextWord)) {
                            nextFrontier.add(nextWord);
                        }
                    }

                    letters[i] = original;
                }
            }

            beginFrontier = nextFrontier;
            length++;
        }

        return 0;
    }
}
